const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const it = $input.first().json; const b = it.body || {};
const tipo = String(b.tipo || '');
if (tipo !== 'pedidos') return [{ json: { ok: true, cancelar: false, tipo, id: b.id, instrucao: b.instrucao } }];
// Pedido: Synapse só cria e cancela. Não existe "alterar pedido".
const id = String(b.id || '').trim();
if (!/^[A-Za-z0-9._ -]{1,140}$/.test(id)) return fail(400, 'id do pedido ausente ou inválido');
if (!/cancel/i.test(String(b.instrucao || ''))) return fail(400, 'Pedidos só podem ser criados ou cancelados; alteração de pedido não existe');
const falta = ['ERPNEXT_DOMAIN', 'HARMONIA_DOMAIN'].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO: variáveis ausentes no Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO');
// Identidade: SOMENTE a sessão do Ritmo (cookie sid). Nome/perfil/instrucao enviados pelo navegador NÃO são prova.
const cookie = String((it.headers || {}).cookie || '');
const m = cookie.match(/(?:^|;\s*)sid=([^;]+)/);
if (!m || m[1] === 'Guest') return fail(401, 'IDENTIDADE_NAO_VERIFICAVEL: a sessão do Ritmo não chegou ao Harmonia — cancelamento recusado (nenhuma alteração feita)', 'IDENTIDADE_NAO_VERIFICAVEL');
return [{ json: { ok: true, cancelar: true, id, instrucao: String(b.instrucao).slice(0, 300), sid: m[1] } }];

const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const user = ($input.first().json || {}).message;
if (!user || user === 'Guest') return fail(401, 'IDENTIDADE_NAO_VERIFICAVEL: sessão do Ritmo inválida ou expirada — cancelamento recusado', 'IDENTIDADE_NAO_VERIFICAVEL');
const c = $('Classifica Requisição').first().json;
return [{ json: { ok: true, user, sid: c.sid, id: c.id, instrucao: c.instrucao } }];

const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const v = $('Valida usuário').first().json;
const doc = ($input.first().json || {}).data || {};
const roles = (doc.roles || []).map(r => r.role);
const permitidas = ['Synapse Lojista', 'Synapse Administrador'];
if (!roles.some(r => permitidas.includes(r))) return fail(403, 'SEM_PERMISSAO: o usuário ' + v.user + ' não possui Role autorizada a cancelar pedidos (Synapse Lojista ou Synapse Administrador) — nada foi alterado', 'SEM_PERMISSAO');
const motivo = 'Cancelamento solicitado por ' + v.user + ' (Role validada no Ritmo). Contexto: ' + v.instrucao;
return [{ json: { ok: true, user: v.user, id: v.id, motivo, l3: { funcao: 'processar_pedido', argumentos: { acao: 'cancelar', id_pedido: v.id, motivo }, conversa_id: null, tenant_id: null } } }];

const r = $input.first().json; const a = $('Autoriza solicitante').first().json;
if (r.sucesso === true) {
  const resumo = r.ja_cancelado ? 'Pedido ' + a.id + ' já estava cancelado (nada alterado)' : 'Pedido ' + a.id + ' cancelado no Ritmo e confirmado';
  return [{ json: { status: 200, body: { sucesso: true, resumo, operation_id: r.operation_id, solicitante: a.user, etapas: (r.dados && r.dados.etapas) || [] } } }];
}
const m = r.erro || 'Cancelamento não executado';
return [{ json: { status: r.hold ? 409 : 502, body: { sucesso: false, erro: m, message: m, hold: !!r.hold, operation_id: r.operation_id || null, etapa_pendente: r.etapa_pendente || null } } }];

const fail = (status, m, codigo) => [{ json: { status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];

const it = $input.first().json || {}; const e = it.error || it;
const up = Number(e.httpCode || e.statusCode || 0);
const m = (up === 401 || up === 403) ? 'IDENTIDADE_NAO_VERIFICAVEL: o Ritmo recusou a sessão (HTTP ' + up + ') — cancelamento recusado' : 'Falha ao validar identidade no Ritmo' + (up ? ' (HTTP ' + up + ')' : '');
return [{ json: { status: (up === 401 || up === 403) ? 401 : 502, body: { sucesso: false, erro: m, message: m, codigo: 'IDENTIDADE_NAO_VERIFICAVEL' } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao acionar a execu\u00e7\u00e3o do cancelamento (Lyra L3)" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "lyra-l3" } } }];

const referencia = "Campos válidos por tipo_entidade (ERPNext):
cliente (Customer): customer_name, mobile_no, email_id, tax_id, customer_group
produto (Item): item_name, standard_rate (preco), description, item_group
fornecedor (Supplier): supplier_name, mobile_no, email_id, tax_id, supplier_group";
const system_prompt = 'Você traduz uma instrução em português pra um JSON de campos a atualizar num ERP. Responda APENAS com um objeto JSON plano {"campo": valor, ...}, só com os campos que a instrução realmente pede pra mudar, usando exatamente os nomes de campo da referência abaixo. Não invente campo fora da lista. Se a instrução não corresponder a nenhum campo conhecido, responda {}.

' + referencia;
const user_prompt = 'tipo_entidade: ' + $json.tipo + '
instrução: ' + $json.instrucao;
const gemini = { system_instruction: { parts: [{ text: system_prompt }] }, contents: [{ role: 'user', parts: [{ text: user_prompt }] }], generationConfig: { response_mime_type: 'application/json' } };
return [{ json: { tipo: $json.tipo, id: $json.id, gemini } }];

const meta = $('Monta Prompt de Interpretação').first().json;
const resp = $input.first().json;
let diff = {};
try { diff = JSON.parse(resp.candidates?.[0]?.content?.parts?.[0]?.text || '{}'); } catch (e) { throw new Error('Lyra não conseguiu interpretar a instrução'); }
if (!Object.keys(diff).length) throw new Error('Nenhum campo reconhecido nessa instrução');
return [{ json: { funcao: 'gerenciar_cadastro', argumentos: { acao: 'editar', tipo_entidade: meta.tipo, id_entidade: meta.id, dados_cliente: diff }, _resumo_campos: Object.keys(diff).join(', ') } }];

const meta = $('Extrai Diff Estruturado').first().json; const r = $input.first().json;
if (!r.sucesso) return [{ json: { status: 200, body: { erro: r.erro || 'Não foi possível salvar a alteração' } } }];
return [{ json: { status: 200, body: { resumo: 'Campos atualizados: ' + meta._resumo_campos } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao alterar o registro" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "lyra-alterar" } } }];
